```jsx
// 快速定位是哪个组件慢
// 在 React DevTools Profiler 中录制
// 查看每个组件的渲染耗时
```

---

## 常见根因及验证方法

### 1. 渲染期间的同步重计算

```jsx
// ❌ 典型问题：每次渲染都执行昂贵计算
function Dashboard({ data }) {
  // 这在每次渲染时都会执行
  const processedData = data
    .filter(item => item.active)
    .map(item => expensiveTransform(item))  // 假设耗时 2s
    .sort((a, b) => b.value - a.value);

  return <Chart data={processedData} />;
}

// ✅ 修复：用 useMemo 缓存
function Dashboard({ data }) {
  const processedData = useMemo(() => 
    data
      .filter(item => item.active)
      .map(item => expensiveTransform(item))
      .sort((a, b) => b.value - a.value),
    [data]  // 只在 data 变化时重新计算
  );

  return <Chart data={processedData} />;
}
```

### 2. 一次性渲染大量 DOM 节点

```jsx
// ❌ 问题：渲染 10000 行表格
function DataTable({ rows }) {
  return (
    <table>
      {rows.map(row => <Row key={row.id} data={row} />)}
      {/* 10000 个 Row 组件同时挂载 */}
    </table>
  );
}

// ✅ 修复方案 A：虚拟列表
import { FixedSizeList } from 'react-window';

function DataTable({ rows }) {
  return (
    <FixedSizeList
      height={600}
      itemCount={rows.length}
      itemSize={35}
      width="100%"
    >
      {({ index, style }) => (
        <Row style={style} data={rows[index]} />
      )}
    </FixedSizeList>
  );
}

// ✅ 修复方案 B：分页（更简单）
function DataTable({ rows }) {
  const [page, setPage] = useState(0);
  const pageSize = 50;
  const visibleRows = rows.slice(page * pageSize, (page + 1) * pageSize);

  return (/* ... */);
}
```

### 3. 不必要的全树重渲染

```jsx
// ❌ 问题：顶层 state 变化导致整棵树重渲染
function Dashboard() {
  const [filter, setFilter] = useState('all');
  const [data, setData] = useState([]);

  return (
    <div>
      <ExpensiveChart data={data} />      {/* filter 变化时也重渲染 */}
      <ExpensiveTable data={data} />      {/* filter 变化时也重渲染 */}
      <FilterBar value={filter} onChange={setFilter} />
    </div>
  );
}

// ✅ 修复：memo 阻断不必要的重渲染
const ExpensiveChart = memo(function ExpensiveChart({ data }) {
  return (/* ... */);
});

const ExpensiveTable = memo(function ExpensiveTable({ data }) {
  return (/* ... */);
});
```

### 4. 第三方库在主线程同步初始化

```jsx
// ❌ 问题：图表库在渲染时同步初始化
function ChartWidget({ data }) {
  // 某些图表库的初始化可能耗时 3-5s
  return <HeavyChartLibrary data={data} options={complexOptions} />;
}

// ✅ 修复：懒加载 + Suspense
const HeavyChartLibrary = lazy(() => import('./HeavyChartLibrary'));

function ChartWidget({ data }) {
  return (
    <Suspense fallback={<ChartSkeleton />}>
      <HeavyChartLibrary data={data} options={complexOptions} />
    </Suspense>
  );
}
```

### 5. useEffect 链式触发

```jsx
// ❌ 问题：瀑布式 effect，每个都触发重渲染
function Dashboard() {
  const [raw, setRaw] = useState(null);
  const [processed, setProcessed] = useState(null);
  const [filtered, setFiltered] = useState(null);

  useEffect(() => {
    fetchData().then(setRaw);           // 渲染 1
  }, []);

  useEffect(() => {
    if (raw) setProcessed(process(raw)); // 渲染 2
  }, [raw]);

  useEffect(() => {
    if (processed) setFiltered(filter(processed)); // 渲染 3
  }, [processed]);
}

// ✅ 修复：合并为单次状态更新
function Dashboard() {
  const [displayData, setDisplayData] = useState(null);

  useEffect(() => {
    fetchData().then(raw => {
      const processed = process(raw);
      const filtered = filter(processed);
      setDisplayData(filtered);          // 只触发一次渲染
    });
  }, []);
}
```

