### 修复方向三：子组件不必要的重渲染

```jsx
// ❌ 父组件任何 state 变化，所有图表都重渲染
function Dashboard({ data }) {
  const [selectedTab, setSelectedTab] = useState('overview');

  return (
    <>
      <TabBar value={selectedTab} onChange={setSelectedTab} />
      <RevenueChart data={data.revenue} />    {/* 切 tab 时不需要重渲染 */}
      <UserChart data={data.users} />         {/* 同上 */}
      <HeavyDataGrid data={data.metrics} />  {/* 同上 */}
    </>
  );
}

// ✅ memo 阻断不必要的渲染
const RevenueChart = memo(function RevenueChart({ data }) {
  return <ExpensiveChart data={data} />;
});

// ✅ 回调函数用 useCallback 稳定引用
const handleExport = useCallback(() => {
  exportData(data);
}, [data]);
```

