### 修复方向四：初始渲染阻塞——延迟非关键内容

```jsx
// ✅ 优先渲染用户最先看到的内容
function Dashboard({ data }) {
  const [showSecondary, setShowSecondary] = useState(false);

  useEffect(() => {
    // 主内容渲染完成后，再加载次要面板
    const id = requestIdleCallback(() => setShowSecondary(true));
    return () => cancelIdleCallback(id);
  }, []);

  return (
    <>
      {/* 关键内容：立即渲染 */}
      <KPICards data={data.kpis} />
      <MainChart data={data.primary} />

      {/* 次要内容：空闲时渲染 */}
      {showSecondary && (
        <>
          <ActivityFeed data={data.feed} />
          <DetailPanel data={data.details} />
        </>
      )}
    </>
  );
}
```

