## 配套优化：防止重复渲染

### 1. 数据处理移出渲染路径

```tsx
// ❌ 错误：每次渲染都重新计算
function Dashboard() {
  const { data } = useMetrics();

  // 这个 sort + filter 在每次渲染时都执行
  const processedData = data
    .filter(row => row.value > 0)
    .sort((a, b) => b.value - a.value);

  return <VirtualizedMetricsTable data={processedData} />;
}

// ✅ 正确：用 useMemo 缓存计算结果
function Dashboard() {
  const { data } = useMetrics();
  const [filterValue, setFilterValue] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: 'value',
    direction: 'desc'
  });

  const processedData = useMemo(() => {
    let result = data.filter(row => {
      if (!filterValue) return row.value > 0;
      return row.name.toLowerCase().includes(filterValue.toLowerCase()) 
        && row.value > 0;
    });

    result.sort((a, b) => {
      const multiplier = sortConfig.direction === 'desc' ? -1 : 1;
      return (a[sortConfig.key] - b[sortConfig.key]) * multiplier;
    });

    return result;
  }, [data, filterValue, sortConfig]); // 依赖项精确声明

  return (
    <VirtualizedMetricsTable 
      data={processedData}
      onSort={setSortConfig}
    />
  );
}
```

### 2. 搜索/过滤防抖

```tsx
// hooks/useDebouncedFilter.ts
function useDebouncedFilter(data: MetricsRow[], delay = 300) {
  const [inputValue, setInputValue] = useState('');
  const [filterValue, setFilterValue] = useState('');

  // 用户输入立即更新 input，但过滤计算延迟触发
  useEffect(() => {
    const timer = setTimeout(() => {
      setFilterValue(inputValue);
    }, delay);
    return () => clearTimeout(timer);
  }, [inputValue, delay]);

  const filteredData = useMemo(
    () => data.filter(row => 
      row.name.toLowerCase().includes(filterValue.toLowerCase())
    ),
    [data, filterValue]
  );

  return { inputValue, setInputValue, filteredData };
}
```

### 3. 初始加载：优先渲染关键内容

```tsx
// 让仪表盘的关键 KPI 卡片先渲染，表格延迟加载
function Dashboard() {
  const { data, isLoading } = useMetrics();
  const [showTable, setShowTable] = useState(false);

  // KPI 卡片渲染完成后，在下一个空闲帧加载表格
  useEffect(() => {
    // requestIdleCallback 在浏览器空闲时执行，不阻塞关键渲染
    const id = requestIdleCallback(
      () => setShowTable(true),
      { timeout: 2000 } // 最多等待 2s，超时强制执行
    );
    return () => cancelIdleCallback(id);
  }, []);

  return (
    <div>
      {/* 优先渲染：KPI 摘要卡片 */}
      <KPISummaryCards data={data?.summary} isLoading={isLoading} />

      {/* 延迟渲染：大型数据表格 */}
      {showTable ? (
        <Suspense fallback={<TableSkeleton />}>
          <VirtualizedMetricsTable data={data?.rows ?? []} />
        </Suspense>
      ) : (
        <TableSkeleton />
      )}
    </div>
  );
}
```

