## 验证优化效果

```tsx
// 开发环境性能标记，生产环境自动剥离
function useRenderTiming(componentName: string) {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return;

    performance.mark(`${componentName}-rendered`);

    // 测量从导航开始到组件渲染完成的时间
    try {
      performance.measure(
        `${componentName} 首次渲染耗时`,
        'navigationStart',
        `${componentName}-rendered`
      );

      const [measure] = performance.getEntriesByName(
        `${componentName} 首次渲染耗时`
      );
      console.log(`[Perf] ${componentName}: ${measure.duration.toFixed(0)}ms`);
    } catch {
      // navigationStart 在某些场景下不可用
    }
  }, []); // 空依赖 = 仅首次渲染后执行
}

// 在表格组件中使用
function VirtualizedMetricsTable(props) {
  useRenderTiming('MetricsTable');
  // ...
}
```

