## 第四步：添加崩溃前的防御日志

```kotlin
class MyApplication : Application() {

    override fun onCreate() {
        // 在最开始捕获所有未处理异常
        val defaultHandler = Thread.getDefaultUncaughtExceptionHandler()
        Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->
            // 写入本地文件，下次启动时上报
            saveCrashToFile(throwable)
            defaultHandler?.uncaughtException(thread, throwable)
        }

        super.onCreate()
        logStep("after super.onCreate")

        // 每个初始化步骤单独 try-catch 定位
        tryInit("Database") { initDatabase() }
        tryInit("Analytics") { initAnalytics() }
        tryInit("DI") { initDependencyInjection() }
    }

    private fun tryInit(name: String, block: () -> Unit) {
        try {
            block()
            Log.d("AppInit", "$name: SUCCESS")
        } catch (e: Throwable) {
            Log.e("AppInit", "$name: FAILED", e)
            throw e // 重新抛出，保持原有崩溃行为
        }
    }
}
```

