}, []);
```

#### 🟡 可能性第二：图片格式/解码问题

```javascript
// iOS 对某些格式处理与 Android 不同
// HEIC、WebP、某些 EXIF 方向的 JPEG 都可能有问题

const SafeImage = ({ uri, ...props }) => {
  const [error, setError] = useState(false);
  const [dimensions, setDimensions] = useState(null);

  useEffect(() => {
    // 预检查图片，捕获解码问题
    Image.getSize(
      uri,
      (width, height) => {
        // iOS 上超大图片要警惕
        if (width * height > 20_000_000) { // 2000万像素
          console.warn('图片过大，可能导致崩溃:', { width, height, uri });
          // 使用缩略图替代
        }
        setDimensions({ width, height });
      },
      (error) => {
        console.error('图片加载失败:', error);
        setError(true);
      }
    );
  }, [uri]);

  if (error) return <FallbackComponent />;
  return <Image source={{ uri }} onError={() => setError(true)} {...props} />;
};
```

#### 🟡 如果真的是Bridge序列化问题

```javascript
// 症状：传递给 native 的数据结构有问题
// 典型错误数据

// ❌ 可能导致序列化崩溃的情况
const badData = {
  imageData: new Uint8Array(buffer),  // 不能直接传
  callback: () => {},                  // 函数不能序列化
  circularRef: obj,                    // 循环引用
  undefinedValue: undefined,           // 某些情况下有问题
  nan: NaN,                           // 数字异常值
  infinity: Infinity,
};

// ✅ 传给 native 前清洗数据
const sanitizeForBridge = (data) => {
  return JSON.parse(JSON.stringify(data, (key, value) => {
    if (typeof value === 'function') return undefined;
    if (typeof value === 'number' && !isFinite(value)) return null;
    if (value === undefined) return null;
    return value;
  }));
};

// 如果传递 base64 图片数据
// ❌ 不要通过 bridge 传大型 base64
const base64Image = await getBase64(); // 可能几MB
nativeModule.processImage(base64Image); // 崩溃风险极高

// ✅ 传文件路径，让 native 自己读
nativeModule.processImageAtPath(filePath); // 安全
```

#### 🔵 线程安全问题

```javascript
// iOS 的 UIKit 必须在主线程操作
// React Native 有时会在错误线程更新 UI

const ImageScreen = () => {
  const [images, setImages] = useState([]);

  useEffect(() => {
    fetchImages().then(data => {
      // ❌ 如果 fetchImages 在非主线程回调
      setImages(data);

      // ✅ 确保在主线程
      // React Native 的 setState 通常是安全的
      // 但如果用了原生模块回调，要注意
