  }, []);
};

// 如果用了原生模块
NativeModules.ImageProcessor.process(uri, (result) => {
  // 这个回调可能不在主线程
  // ✅ 强制回到主线程
  requestAnimationFrame(() => {
    setProcessedImage(result);
  });
});
