// 启动参数
-Dio.netty.allocator.type=pooled
-Dio.netty.allocator.numDirectArenas=0  // 禁用直接内存（如果泄漏）

// 或使用堆外缓存存储大对象
// 使用 Chronicle Map 或 OHC
OHCache<String, byte[]> offHeapCache = OHCacheBuilder
    .<String, byte[]>newBuilder()
    .keySerializer(stringSerializer)
    .valueSerializer(bytesSerializer)
    .capacity(2L * 1024 * 1024 * 1024) // 2GB 堆外
    .build();
```

