# Canvas 高DPI模糊问题解决方案

## 问题根因

```
CSS尺寸: 500×300px
                    ↓
普通屏幕 (DPR=1)    高DPI屏幕 (DPR=2)
位图: 500×300px     位图: 500×300px  ← 问题所在
物理像素: 500×300   物理像素: 1000×600
结果: 清晰          结果: 拉伸模糊 ✗
```

## 核心修复方案

```javascript
function setupHiDPICanvas(canvas, width, height) {
    const dpr = window.devicePixelRatio || 1;

    // 1. 位图尺寸 × DPR（解决模糊）
    canvas.width  = width  * dpr;
    canvas.height = height * dpr;

    // 2. CSS尺寸保持原始大小（保持布局）
    canvas.style.width  = `${width}px`;
    canvas.style.height = `${height}px`;

    // 3. 缩放上下文，让绘图代码无需改动
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    return ctx;
}

// 使用方式（绘图代码完全不用修改）
const canvas = document.getElementById('myCanvas');
const ctx = setupHiDPICanvas(canvas, 500, 300);

ctx.font = '16px Arial';
ctx.fillText('清晰文字', 50, 50);  // 坐标仍用CSS像素
```

## 处理窗口缩放/移动场景

```javascript
class HiDPICanvas {
    constructor(canvasEl, width, height) {
        this.canvas = canvasEl;
        this.width  = width;
        this.height = height;
        this.ctx    = null;
        this.currentDPR = null;

        this.setup();
        this.watchDPRChange();  // 监听屏幕变化
    }

    setup() {
        const dpr = window.devicePixelRatio || 1;

        if (dpr === this.currentDPR) return; // 无变化则跳过
        this.currentDPR = dpr;

        this.canvas.width  = this.width  * dpr;
        this.canvas.height = this.height * dpr;
        this.canvas.style.width  = `${this.width}px`;
        this.canvas.style.height = `${this.height}px`;

        this.ctx = this.canvas.getContext('2d');
        this.ctx.scale(dpr, dpr);
    }

    watchDPRChange() {
        // 用户把窗口拖到不同DPR的屏幕时触发
        const mediaQuery = window.matchMedia(
            `(resolution: ${window.devicePixelRatio}dppx)`
        );

        mediaQuery.addEventListener('change', () => {
            this.setup();
            this.redraw?.(); // 触发重绘回调
        });
    }
}
```

## 与 ResizeObserver 结合（响应式Canvas）

```javascript
function createResponsiveCanvas(canvas, drawFn) {
    let ctx;

    function resize(width, height) {
        const dpr = window.devicePixelRatio || 1;

        canvas.width  = Math.round(width  * dpr);
        canvas.height = Math.round(height * dpr);  // ⚠️ 取整避免亚像素
        canvas.style.width  = `${width}px`;
        canvas.style.height = `${height}px`;

        ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);

        drawFn(ctx, width, height);  // 重绘
    }

    const observer = new ResizeObserver(entries => {
        const { width, height } = entries[0].contentRect;
        resize(width, height);
    });

    observer.observe(canvas);
    return () => observer.disconnect(); // 返回清理函数
}
```

## 常见错误对照

```javascript
// ❌ 错误1：只改CSS尺寸
canvas.style.width  = '500px';   // 位图还是默认300×150

// ❌ 错误2：只改位图尺寸，忘记scale
canvas.width = 1000;             // 坐标系变了，所有绘图偏移

// ❌ 错误3：重复scale（每次重绘都调用）
ctx.scale(dpr, dpr);             // 多次调用会叠加！
ctx.scale(dpr, dpr);             // → 实际缩放 dpr²

// ✅ 正确：重绘前重置变换
function redraw() {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // 替代clearRect+scale
    ctx.clearRect(0, 0, width, height);
    // ... 绘图
}
```

