```javascript
// 确认修复是否生效
const dpr = window.devicePixelRatio;
console.table({
    'devicePixelRatio' : dpr,
    'canvas.width'     : canvas.width,          // 应为 CSS宽 × DPR
    'canvas.height'    : canvas.height,
    'style.width'      : canvas.style.width,    // 应为原始CSS尺寸
    '比例正确'         : canvas.width === parseInt(canvas.style.width) * dpr
